            const response = await page.goto(`https://localhost:44317${path}`, { waitUntil: 'networkidle' });
            if (response.status() !== 200) throw new Error(`Failed route ${path}`);
            if (await page.locator('h1').count() !== 1) throw new Error(`Missing or duplicate heading: ${path}`);
            if ((await page.locator('body').innerText()).includes('Could not render component')) throw new Error(`Block fallback: ${path}`);
            for (const image of await page.locator('img').all()) {
                await image.scrollIntoViewIfNeeded();
                await image.evaluate(img => img.decode());
            }
            const overflow = await page.evaluate(() => document.documentElement.scrollWidth > innerWidth);
            if (overflow) throw new Error(`Horizontal overflow at ${width}px: ${path}`);
            if (path === '/') {
                if (await page.locator('#articles article').count() !== 2) throw new Error('Expected two posts');
            } else if (await page.locator('.article-copy h2').count() < 3) {
                throw new Error(`Article body missing: ${path}`);
            }
            await page.evaluate(() => scrollTo(0, 0));
            const label = path === '/' ? 'home' : path.split('/')[1];
            await page.screenshot({ path: `../artifacts/${label}-${width}.png`, fullPage: true });
            console.log(`PASS ${width}px ${path}: heading, blocks, images, layout`);
        }
    }
    await page.goto('https://localhost:44317/');
    await page.locator('#articles article a').first().click();
    await page.waitForURL('**/from-conversation-to-published-content/');
    await page.getByRole('link', { name: 'All stories' }).click();
    await page.waitForURL('**/#articles');
    console.log('PASS article navigation and return to listing');
    if (errors.length) throw new Error(errors.join('\n'));
    console.log('PASS no page errors or failed HTTP responses');
} finally {
    await browser.close();
}

